mapper.select:
SELECT level_date AS metricDate,
       end_volume_liters AS metricValue
FROM tb_tank_daily_level
WHERE tank_id = #{tankId}
  AND level_date BETWEEN #{from} AND #{to}
ORDER BY level_date ASC

SELECT end_volume_liters
FROM tb_tank_daily_level
WHERE tank_id = #{tankId}
  AND level_date < #{beforeDate}
ORDER BY level_date DESC
LIMIT 1

mapper.delete:
DELETE FROM tb_tank_daily_level
WHERE tank_id = #{tankId}
  AND level_date = #{levelDate}
  AND source = 'EXCEL'
